create or replace function atlas.transition_implementation_connected_source_authorization_self_api_v1(p_implementation_case_source_id uuid,p_source_id uuid,p_to_state text,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path to 'pg_catalog','atlas','auth' as $function$ declare v_source_state text; begin if not atlas.implementation_source_authorized_self_v1(p_implementation_case_source_id) then raise exception 'Setup-sponsor authority required.' using errcode='42501'; end if; if p_to_state not in ('connected','error','reauthorization_required','revoked') then raise exception 'Unsupported implementation source transition.' using errcode='22023'; end if; if not exists (select 1 from atlas.implementation_case_sources cs join atlas.connected_sources s on s.id=cs.connected_source_id where cs.id=p_implementation_case_source_id and s.id=p_source_id and s.custodian_user_id=auth.uid()) then raise exception 'Implementation connected source custody mismatch.' using errcode='42501'; end if; update atlas.connected_sources set authorization_state=p_to_state,revoked_at=case when p_to_state='revoked' then now() else null end,metadata=metadata||coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_source_id; v_source_state:=case when p_to_state='connected' then 'connected' when p_to_state in ('error','reauthorization_required','revoked') then 'blocked' else 'authorization_pending' end; update atlas.implementation_case_sources set source_state=v_source_state,usable_at=case when p_to_state='connected' then coalesce(usable_at,now()) else null end,blocker=case when p_to_state='connected' then null else coalesce(p_metadata->>'reason',p_to_state) end,updated_at=now() where id=p_implementation_case_source_id; return jsonb_build_object('ok',true,'implementationCaseSourceId',p_implementation_case_source_id,'sourceId',p_source_id,'authorizationState',p_to_state,'sourceState',v_source_state); end; $function$; create or replace function public.transition_implementation_connected_source_authorization_self_api_v1(p_implementation_case_source_id uuid,p_source_id uuid,p_to_state text,p_metadata jsonb default '{}'::jsonb) returns jsonb language sql security invoker set search_path to 'pg_catalog','atlas','public' as $function$ select atlas.transition_implementation_connected_source_authorization_self_api_v1(p_implementation_case_source_id,p_source_id,p_to_state,p_metadata); $function$; revoke all on function atlas.transition_implementation_connected_source_authorization_self_api_v1(uuid,uuid,text,jsonb) from public; revoke all on function public.transition_implementation_connected_source_authorization_self_api_v1(uuid,uuid,text,jsonb) from public,anon; grant execute on function atlas.transition_implementation_connected_source_authorization_self_api_v1(uuid,uuid,text,jsonb) to authenticated; grant execute on function public.transition_implementation_connected_source_authorization_self_api_v1(uuid,uuid,text,jsonb) to authenticated;